px;text-align:center;color:var(--muted)}.results,.preview{margin-top:24px;padding-top:24px;border-top:1px solid var(--border)}.table-scroll{overflow:auto;max-height:600px}table{border-collapse:collapse;width:100%;font-size:13px}th,td{border-bottom:1px solid var(--border);padding:13px 12px;text-align:left;max-width:420px;overflow-wrap:anywhere}th{font-size:12px;color:var(--muted);background:var(--panel2);position:sticky;top:0}.sub{display:block;margin-top:5px}pre,code{white-space:pre-wrap;overflow-wrap:anywhere}details{color:var(--muted);font-size:12px}summary{cursor:pointer}details .el-button{margin-top:12px}.policy-row{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:24px 0;border-bottom:1px solid var(--border)}.policy-row p{color:var(--muted);font-size:13px;line-height:1.7;margin-bottom:0}.policy-row label{display:flex;align-items:center;white-space:nowrap;font-size:13px}.settings>h3{margin-bottom:12px}.layout:not(.embedded) :deep(.platform-nav button){flex-direction:row;justify-content:flex-start;gap:10px;padding:10px 12px;font-size:13px}.layout.embedded>header{width:var(--sidebar-width);flex-basis:var(--sidebar-width);padding:12px 6px}.embedded header>b{display:none}.embedded nav{margin:0 0 12px}.embedded nav button{flex-direction:column;justify-content:center;gap:5px;padding:8px 0;min-height:54px;font-size:11px}button:focus-visible,input:focus-visible,summary:focus-visible{outline:2px solid var(--brand);outline-offset:3px}@media(max-width:760px){main{padding:18px 14px}.layout>header{width:var(--sidebar-width);flex-basis:var(--sidebar-width);padding:12px 6px}.layout header>b{display:none}.layout nav button,.layout:not(.embedded) :deep(.platform-nav button){flex-direction:column;justify-content:center;text-align:center;font-size:11px;padding:8px 0;gap:5px}.grid{grid-template-columns:1fr}.card{padding:16px}.policy-row{align-items:flex-start;flex-direction:column;gap:12px}.scope{align-items:stretch}.scope>label{width:100%}}
